old12 = '''{"i":"arshan-12","d":"arshan","n":"Второй водопад Кынгарги","x":"Продолжение тропы за первым водопадом; красивее и заметно менее проходное место.","c":["photo","rest"],"v":"partial","s":false,"p":"https://www.kp.ru/russia/bajkal/places/sibirskie-alpy/","u":"https://www.kp.ru/russia/bajkal/places/sibirskie-alpy/","t":"Вероятно","o":"Оцениваем время и состояние тропы; не обязательная точка."}'''
new12 = '''{"i":"arshan-12","d":"arshan","n":"Второй водопад Кынгарги","x":"Водопад выше первого по ущелью Кынгарги — место реальное, но сейчас доступ дальше первого водопада ограничен.","c":["photo","rest"],"v":"verified","s":false,"p":"https://www.visitburyatia.ru/places/section-144/item-1666/","u":"https://tunkapark.ru/tpost/yz6svh1hs1-vopros-otvet","t":"Подтверждено","o":"Сейчас не планируем: при действующем особом противопожарном режиме доступ к другим водопадам выше первого ограничен."}'''
