new20 = '''{"i":"arshan-20","d":"arshan","n":"Культовое место Буха-Нойон — дальний вид","x":"Белая мраморная скала в Тункинских гольцах у Торов — одна из главных сакральных доминант долины, хорошо видимая уже с федеральной дороги.","c":["photo","culture"],"v":"verified","s":true,"p":"https://tunkapark.ru/objects/kultovoe-mesto-bukha-nojon","u":"https://ias.burpriroda.ru/oopt/burchudo/raion.php?ELEMENT_ID=7584&SECTION_ID=7584","t":"Подтверждено","o":"Для нашей поездки используем безопасный дальний вид с района федеральной дороги; самостоятельный подъезд к самой скале не планируем."}'''
